Task.Triggers:
{#- LogonTrigger fires when the user named by UserId logs on. Without a UserId it fires for every user and registering it needs elevation; with the user's own SID it does not. #}

	true
	{{ user_sid }}

Task.Principals:
{#- InteractiveToken runs the task as the logged-on user, only while that user is logged on, with no stored password; LeastPrivilege is the user's unelevated token (RunLevelType). #}

	{{ user_sid }}
	InteractiveToken
	LeastPrivilege

Task.Settings:
{#- IgnoreNew (MultipleInstancesPolicy): a run requested while the daemon runs starts nothing; the daemon also takes its own lock. #}
IgnoreNew
{#- A laptop on battery still serves its builds. #}
false
false
{#- `schtasks /End` and `/Delete` may end the daemon. #}
true
{#- AllowStartOnDemand is what lets `schtasks /Run` start the task. #}
true
true
false
{#- PT0S (an ISO 8601 duration of zero) is no execution time limit: the schema's default of 72 hours would end the daemon. #}
PT0S
{#- Priority 4 is the normal process priority class; the default, 7, is below normal and would slow the builds the daemon serves. #}
4

Task.Actions:
{#- Command is the runtime executable `stow setup` ran from, Arguments its `daemon` command naming the run directory this task serves. #}

	{{ program }}
	{{ arguments }}
